head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    $p.executeSubmission("submission1");
};
scwin.checkVal = function() {
	const left = WebSquare.wUnit.getDomById('tabControl1_btn_scrollLeft').getAttribute('tabindex');
	const submenu = WebSquare.wUnit.getDomById('tabControl1_btn_submenu').getAttribute('tabindex');
	const right = WebSquare.wUnit.getDomById('tabControl1_btn_scrollRight').getAttribute('tabindex');
    return left == null && submenu == null && right == null;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "400");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
